[2016-09-19T00:20:25Z | pdominique | comment]
This code works for me (Homie 1.5 I believe), maybe you can try it to see if this works for you too:

```
// BME280   Wemos D1 Mini
// VIN -->  3V3
// GND -->  G
// SCL -->  D1
// SDA -->  D2

#include <Homie.h>
#include <Wire.h>
#include <SPI.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_BME280.h>

#define SEALEVELPRESSURE_HPA (1013.25)

Adafruit_BME280 bme; // I2C

const int TEMPERATURE_INTERVAL = 5;
const int HUMIDITY_INTERVAL = 10;
const int PRESSURE_INTERVAL = 15;

unsigned long lastTemperatureSent = 0;
unsigned long lastHumiditySent = 0;
unsigned long lastPressureSent = 0;

HomieNode weatherNode("weather", "weather");

void setupHandler() {
  if (!bme.begin()) {
    Serial.println("Could not find a valid BME280 sensor, check wiring!");
    while (1);
  }
}

void loopHandler() {
  // Temperature
  if (millis() - lastTemperatureSent >= TEMPERATURE_INTERVAL * 1000UL || lastTemperatureSent == 0) {
    float temperature = bme.readTemperature();
    Serial.print("Temperature = ");
    Serial.print(temperature);
    Serial.println(" *C");
    if (Homie.setNodeProperty(weatherNode, "temperature", String(temperature), true)) {
      lastTemperatureSent = millis();
    } else {
      Serial.println("Sending failed");
    }
  }
  // Humidity
  if (millis() - lastHumiditySent >= HUMIDITY_INTERVAL * 1000UL || lastHumiditySent == 0) {
    float humidity = bme.readHumidity();
    Serial.print("Humidity = ");
    Serial.print(humidity);
    Serial.println(" %");
    if (Homie.setNodeProperty(weatherNode, "humidity", String(humidity), true)) {
      lastHumiditySent = millis();
    } else {
      Serial.println("Sending failed");
    }
  }
  // Pressure
  if (millis() - lastPressureSent >= PRESSURE_INTERVAL * 1000UL || lastPressureSent == 0) {
    float pressure = bme.readPressure() / 100.0F;
    Serial.print("Pressure = ");
    Serial.print(pressure);
    Serial.println(" hPa");
    if (Homie.setNodeProperty(weatherNode, "pressure", String(pressure), true)) {
      lastPressureSent = millis();
    } else {
      Serial.println("Sending failed");
    }
  }
}

void setup() {
  Homie.setFirmware("awesome-weather", "1.0.0");
  Homie.setSetupFunction(setupHandler);
  Homie.setLoopFunction(loopHandler);
  Homie.setup();
}

void loop() {
  Homie.loop();
}
```

