import java.io.BufferedReader;
import java.io.InputStreamReader;
import org.apache.http.HttpResponse;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.impl.client.HttpClientBuilder;

public class TC2 {
  public static String accessToken;
  public static void main(String[] args) throws Exception {
    TC2 myTC2 = new TC2();
    accessToken = myTC2.getAuth();  //gets accessToken for future calls; this is working
    String vehicleId = myTC2.getVehicleId(); //gets vehicleId; this is working
    myTC2.openRoof(vehicleId);
  }
  public void openRoof(String vehicleId) throws Exception {
    String realUrl = "https://owner-api.teslamotors.com/api/1/vehicles/"+vehicleId+"/command/sun_roof_control?state=close";
    HttpClient client = HttpClientBuilder.create().build();
    HttpPost request = new HttpPost(realUrl);
    request.setHeader("Authorization","Bearer " + accessToken);
    HttpResponse response = client.execute(request);
    //response.getStatusLine().getStatusCode() = 200
    BufferedReader rd = new BufferedReader(
    new InputStreamReader(response.getEntity().getContent()));
    StringBuffer result = new StringBuffer();
    String line = "";
    while ((line = rd.readLine()) != null) {
      result.append(line);
    }
    //result = {"response":{"reason":"unknown state requested: ","result":false}}
  }
}
```

